#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the dev backup keys for the restore drill (S1-F14-T04; backup-and-restore 2.3, 2.4;
# GC9-12, GC9-17; railway-roles-runbook "Application backup" step 1). Run by the dev custodian
# (RR-236) on their own machine. It prints names, lengths and paths only, never key material.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
PROJECT="apparel-os"
ENVIRONMENT="dev"
SERVICE="backup"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../../.." && pwd)"

banner "Apparel OS · dev backup keys"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the tools"
say "This makes the two key pairs the backup needs and puts only what Railway"
say "must hold onto the 'backup' service in dev. Private keys stay with you."
command -v openssl >/dev/null || { warn "openssl is missing"; exit 1; }
ver=$(openssl version)
say "openssl: $ver"
openssl genpkey -algorithm X25519 >/dev/null 2>&1 || { warn "this openssl cannot make X25519 keys; install OpenSSL 3 (brew install openssl@3)"; exit 1; }
openssl genpkey -algorithm ED25519 >/dev/null 2>&1 || { warn "this openssl cannot make Ed25519 keys; install OpenSSL 3"; exit 1; }
command -v railway >/dev/null || { warn "the railway CLI is missing"; exit 1; }
railway whoami >/dev/null 2>&1 || { warn "railway is not logged in: run 'railway login' first"; exit 1; }
if ! railway variables -p "$PROJECT" -e "$ENVIRONMENT" -s "$SERVICE" --json >/dev/null 2>&1; then
  warn "service '$SERVICE' does not exist in $PROJECT/$ENVIRONMENT yet. Wait until it is created, then run this again."
  exit 1
fi
say "railway: logged in; service '$SERVICE' found in $PROJECT/$ENVIRONMENT."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Choose where the private keys live"
say "Pick a folder on this machine, outside the git repository. Afterwards copy it"
say "into your password manager or another place apart from Railway and every backup."
printf '  %sFolder%s %s[Enter for ~/apparel-os-dev-keys]%s ' "$BOLD" "$RESET" "$DIM" "$RESET"
read -r KEY_DIR || true
KEY_DIR="${KEY_DIR:-$HOME/apparel-os-dev-keys}"
KEY_DIR="${KEY_DIR/#\~/$HOME}"
mkdir -p "$KEY_DIR"
KEY_DIR="$(cd "$KEY_DIR" && pwd)"
case "$KEY_DIR/" in
  "$REPO_ROOT"/*) warn "that folder is inside the repository ($REPO_ROOT). Choose another."; exit 1 ;;
esac
chmod 700 "$KEY_DIR"
say "Keys go to $KEY_DIR (only you can read it)."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Make the two key pairs"
BACKUP_KEY="$KEY_DIR/backup-key.pem"
SIGNING_KEY="$KEY_DIR/backup-signing-key.pem"
if [[ -e "$BACKUP_KEY" || -e "$SIGNING_KEY" ]]; then
  warn "key files already exist in $KEY_DIR."
  if ! confirm "Keep the existing keys and only set Railway from them? (No stops here)"; then
    say "Stopped. Move the old files away first if you really want new keys:"
    say "a new backup key needs '--new-backup-key-version' on the next backup."
    exit 1
  fi
else
  umask 077
  openssl genpkey -algorithm X25519 -out "$BACKUP_KEY"
  openssl genpkey -algorithm ED25519 -out "$SIGNING_KEY"
  chmod 600 "$BACKUP_KEY" "$SIGNING_KEY"
  say "Made backup-key.pem (X25519) and backup-signing-key.pem (Ed25519)."
fi
BACKUP_PUBLIC=$(openssl pkey -in "$BACKUP_KEY" -pubout -outform DER | base64 | tr -d '\n')
SIGNING_PRIVATE=$(openssl pkey -in "$SIGNING_KEY" -outform DER | base64 | tr -d '\n')
SIGNING_PUBLIC=$(openssl pkey -in "$SIGNING_KEY" -pubout -outform DER | base64 | tr -d '\n')
printf '%s\n' "$BACKUP_PUBLIC" > "$KEY_DIR/backup-public-key.b64"
printf '%s\n' "$SIGNING_PUBLIC" > "$KEY_DIR/backup-signing-public-key.b64"
chmod 600 "$KEY_DIR/backup-public-key.b64" "$KEY_DIR/backup-signing-public-key.b64"
note "backup public key: ${#BACKUP_PUBLIC} characters"
note "signing key (private): ${#SIGNING_PRIVATE} characters"
note "signing public key: ${#SIGNING_PUBLIC} characters"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Put the backup's keys on the 'backup' service"
say "Only the 'backup' service in dev gets these three, never 'app' or 'worker':"
step "AOS_BACKUP_PUBLIC_KEY (seals backups)"
step "AOS_BACKUP_SIGNING_KEY (signs backups; private, the backup runner alone holds it)"
step "AOS_BACKUP_SIGNING_PUBLIC_KEY (the restore checks signatures with it)"
say "The backup key's private half (backup-key.pem) is never put on Railway:"
say "you paste it at the restore prompt."
if confirm "Set the three variables now?"; then
  printf '%s' "$BACKUP_PUBLIC" | railway variable set -p "$PROJECT" -e "$ENVIRONMENT" -s "$SERVICE" --skip-deploys --stdin AOS_BACKUP_PUBLIC_KEY >/dev/null
  printf '%s' "$SIGNING_PRIVATE" | railway variable set -p "$PROJECT" -e "$ENVIRONMENT" -s "$SERVICE" --skip-deploys --stdin AOS_BACKUP_SIGNING_KEY >/dev/null
  printf '%s' "$SIGNING_PUBLIC" | railway variable set -p "$PROJECT" -e "$ENVIRONMENT" -s "$SERVICE" --skip-deploys --stdin AOS_BACKUP_SIGNING_PUBLIC_KEY >/dev/null
  unset SIGNING_PRIVATE
  for name in AOS_BACKUP_PUBLIC_KEY AOS_BACKUP_SIGNING_KEY AOS_BACKUP_SIGNING_PUBLIC_KEY; do
    len=$(railway variables -p "$PROJECT" -e "$ENVIRONMENT" -s "$SERVICE" --json 2>/dev/null \
      | python3 -c "import json,sys; print(len(json.load(sys.stdin).get('$name','')))")
    printf '  %s✓ set%s %s on %s (%s characters)\n' "$GREEN" "$RESET" "$name" "$SERVICE" "$len"
  done
else
  SKIPPED+=("the three AOS_BACKUP_* variables on the 'backup' service: run this wizard again")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Keep your copies"
say "Your folder $KEY_DIR now holds:"
step "backup-key.pem: the backup key's private half. Needed at every restore. Secret."
step "backup-signing-key.pem: the signing key. Secret."
step "backup-public-key.b64 and backup-signing-public-key.b64: public halves."
warn "Copy the whole folder into your password manager (or another place apart from"
warn "Railway and from every backup) now. If every copy of backup-key.pem is lost,"
warn "no backup sealed with it can ever be restored (backup-and-restore 2.4)."
pause "Press Enter once your copy is kept"

finish
say "Next: tell Claude the keys are set; it runs the backup and walks you through the restore prompt."
